package com.hmdp.ai.security;import com.hmdp.ai.infra.AiLogSanitizer;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;
class AiLogSanitizerSecretTest {@Test void removesBearerJsonAndProviderSecrets(){String value=AiLogSanitizer.safe("Authorization: Bearer bearer-secret apiKey=sk-live-secret password=database-secret",500);assertThat(value).doesNotContain("bearer-secret","sk-live-secret","database-secret").contains("***");String json=AiLogSanitizer.safe("{\"token\":\"token-secret\",\"secret\":\"hidden-value\"}",500);assertThat(json).doesNotContain("token-secret","hidden-value");}}
